sys_ui_action.script:
// bfd_ui_block_card_temporary — apply a temporary card block, record the
// fulfilment task and write the action to the case audit trail.
(function blockCardTemporaryAction() {
    var TASK_TABLE = 'x_1755386_safetr_0_bfd_case_task';

    var task = new GlideRecord(TASK_TABLE);
    task.initialize();
    task.setValue('case', current.getUniqueValue());
    task.setValue('task_type', 'card_block');
    task.setValue('status', 'complete');
    task.setValue('priority', current.getValue('priority') || 'p2');
    task.setValue(
        'outcome',
        'Temporary card block applied by ' + gs.getUserDisplayName() + ' from the case form.'
    );
    if (current.getValue('assigned_group')) task.setValue('assigned_group', current.getValue('assigned_group'));
    if (current.getValue('assigned_agent')) task.setValue('assigned_agent', current.getValue('assigned_agent'));
    var due = new GlideDateTime();
    task.setValue('due_date', due.getValue());
    var taskId = task.insert();

    current.setValue('card_action', 'temporary_block');
    new bfd_TriageEngine().logAiDecision(current, {
        note:
            'Agent applied a TEMPORARY card block. Fulfilment task ' +
            (taskId ? task.getValue('number') : '(not created)') +
            ' recorded as complete.',
        finalDecision: 'card_action=temporary_block',
    });
    current.update();

    gs.addInfoMessage(
        'Temporary card block applied. A completed "Card block" task has been added to this case and the action is recorded in the audit trail.'
    );
    action.setRedirectURL(current);
})();
